WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) AS prev_paid_at FROM payments), with_gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT method, COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END) AS success_count, COUNT_IF(status = 'SUCCESS') AS success_events, MAX(prev_paid_at) AS ended_at, AVG(amount) AS avg_amount FROM sessionized GROUP BY method ORDER BY method DESC NULLS LAST
